import{_ as s,o as e,c as a,a2 as d}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"Supported institutions","description":"","frontmatter":{"title":"Supported institutions"},"headers":[],"relativePath":"docs/personal-finance/supported-institutions.md","filePath":"docs/personal-finance/supported-institutions.md","lastUpdated":1791955898000}'),n={name:"docs/personal-finance/supported-institutions.md"};function r(i,t,o,l,u,p){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="supported-institutions" tabindex="-1">Supported institutions <a class="header-anchor" href="#supported-institutions" aria-label="Permalink to &quot;Supported institutions&quot;">​</a></h1><p>OrbySystems ships with parsers for a set of banks, card issuers and brokerages, so statements from these institutions can be imported and turned into transactions, holdings and balances automatically — no setup required.</p><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Status is how far a parser&#39;s format has been confirmed on real statements. It decides what OrbySystems does when a statement doesn&#39;t read cleanly.</p><ul><li><span class="status-badge status-well-tested">Verified</span> — at least one real statement has imported cleanly. If a statement doesn&#39;t read, OrbySystems shows what went wrong so you can report it.</li><li><span class="status-badge status-provisional">Provisional</span> — built from the layout of a real statement, and waiting for its first clean import of one. It should work, but is more likely to need a fix for a layout it hasn&#39;t seen. If a statement doesn&#39;t read, OrbySystems shows what went wrong so you can report it.</li><li><span class="status-badge status-untested">Untested</span> — built from public samples or invented data, and never run on a real statement. It may well work, but if it doesn&#39;t, OrbySystems offers <a href="/docs/tools/add-new-institution">Add New Institution</a>, so a parser can be built from a scrambled copy of your statement.</li></ul><h2 id="institutions" tabindex="-1">Institutions <a class="header-anchor" href="#institutions" aria-label="Permalink to &quot;Institutions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Institution</th><th>Status</th><th>Statements read</th></tr></thead><tbody><tr><td>Ameriprise Financial</td><td><span class="status-badge status-untested">Untested</span></td><td>Brokerage statement (PDF)</td></tr><tr><td>Apex Clearing</td><td><span class="status-badge status-untested">Untested</span></td><td>Brokerage statement (PDF)</td></tr><tr><td>Apple Card</td><td><span class="status-badge status-well-tested">Verified</span></td><td>Credit card statement (PDF)</td></tr><tr><td>Bank of America</td><td><span class="status-badge status-well-tested">Verified</span></td><td>Checking and savings, combined checking and savings, and combined statements; credit card statements (PDF)</td></tr><tr><td>BNY Pershing</td><td><span class="status-badge status-untested">Untested</span></td><td>Brokerage statement (PDF)</td></tr><tr><td>Charles Schwab</td><td><span class="status-badge status-well-tested">Verified</span></td><td>Brokerage statement and Retirement Plan Services 401(k) statement (PDF)</td></tr><tr><td>Chase</td><td><span class="status-badge status-well-tested">Verified</span></td><td>Credit card statement (PDF); checking export (CSV)</td></tr><tr><td>Citi</td><td><span class="status-badge status-well-tested">Verified</span></td><td>Credit card statement and annual summary (PDF). Some card layouts are not read yet</td></tr><tr><td>E*TRADE from Morgan Stanley</td><td><span class="status-badge status-provisional">Provisional</span></td><td>Brokerage and stock plan statement (PDF)</td></tr><tr><td>Edward Jones</td><td><span class="status-badge status-untested">Untested</span></td><td>Brokerage statement (PDF)</td></tr><tr><td>Empower</td><td><span class="status-badge status-well-tested">Verified</span></td><td>401(k) plan statement (PDF)</td></tr><tr><td>Empower</td><td><span class="status-badge status-untested">Untested</span></td><td>Brokerage and IRA statement (PDF)</td></tr><tr><td>Fidelity Investments</td><td><span class="status-badge status-well-tested">Verified</span></td><td>Brokerage statement (PDF); positions export (CSV)</td></tr><tr><td>Fidelity NetBenefits</td><td><span class="status-badge status-well-tested">Verified</span></td><td>401(k) statement (PDF) and export (CSV)</td></tr><tr><td>Fidelity Rewards Visa</td><td><span class="status-badge status-well-tested">Verified</span></td><td>Credit card statement (PDF)</td></tr><tr><td>Interactive Brokers</td><td><span class="status-badge status-untested">Untested</span></td><td>Activity statement (PDF)</td></tr><tr><td>J.P. Morgan Wealth Management</td><td><span class="status-badge status-untested">Untested</span></td><td>Investment statement (PDF)</td></tr><tr><td>LPL Financial</td><td><span class="status-badge status-untested">Untested</span></td><td>Investment statement (PDF)</td></tr><tr><td>Merrill</td><td><span class="status-badge status-untested">Untested</span></td><td>Wealth Management statement (PDF)</td></tr><tr><td>Merrill Lynch</td><td><span class="status-badge status-untested">Untested</span></td><td>Cash Management Account statement (PDF)</td></tr><tr><td>Morgan Stanley Global Stock Plan Services</td><td><span class="status-badge status-untested">Untested</span></td><td>Stock plan statement (PDF)</td></tr><tr><td>Morgan Stanley Wealth Management</td><td><span class="status-badge status-untested">Untested</span></td><td>Client statement (PDF)</td></tr><tr><td>Principal Financial Group</td><td><span class="status-badge status-untested">Untested</span></td><td>Retirement statement (PDF)</td></tr><tr><td>Raymond James</td><td><span class="status-badge status-untested">Untested</span></td><td>Brokerage statement (PDF)</td></tr><tr><td>Robinhood</td><td><span class="status-badge status-untested">Untested</span></td><td>Brokerage statement (PDF)</td></tr><tr><td>T. Rowe Price Brokerage</td><td><span class="status-badge status-untested">Untested</span></td><td>Brokerage statement (PDF)</td></tr><tr><td>UBS Financial Services</td><td><span class="status-badge status-untested">Untested</span></td><td>Resource Management Account statement (PDF)</td></tr><tr><td>Vanguard</td><td><span class="status-badge status-provisional">Provisional</span></td><td>Brokerage statement (PDF); activity export (CSV, XLSX)</td></tr><tr><td>Voya</td><td><span class="status-badge status-well-tested">Verified</span></td><td>401(k) plan statement (PDF)</td></tr><tr><td>Wells Fargo</td><td><span class="status-badge status-provisional">Provisional</span></td><td>Checking statement (PDF)</td></tr><tr><td>Wells Fargo Advisors</td><td><span class="status-badge status-untested">Untested</span></td><td>Investment statement (PDF)</td></tr></tbody></table><p>Alongside these, OrbySystems includes a sample institution and a fictional bank and brokerage that power the demo household. They read only invented statements.</p><h2 id="adding-support-yourself" tabindex="-1">Adding support yourself <a class="header-anchor" href="#adding-support-yourself" aria-label="Permalink to &quot;Adding support yourself&quot;">​</a></h2><p>Don&#39;t see your institution, or run into a statement layout an existing parser doesn&#39;t handle? You don&#39;t have to wait for a release — use <a href="/docs/tools/add-new-institution">Add New Institution</a>. It makes a scrambled copy of one of your statements, with your names and numbers replaced, and OrbySystems builds a parser from that copy. OrbySystems tries the result on your real statement before installing it.</p>',10)])])}const g=s(n,[["render",r]]);export{m as __pageData,g as default};
